/* Bài 12.2 — nút: chỉ animate đúng thuộc tính đổi */
.btn {
  background: #2563eb; color: #fff; border: 0; padding: 10px 18px; border-radius: 8px;
  transition: background-color 200ms ease-out;   /* thuộc tính · thời lượng · đường cong */
}
